div.script:

window.addEventListener('DOMContentLoaded', () => {
  // Set Title
  document.title = "eagle.io";

  // Clock
  const clockEl = document.getElementById('liveClock');
  setInterval(() => {
    clockEl.textContent = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
  }, 1000);

  // Scroll to Top
  const scrollTopBtn = document.getElementById('scrollTopBtn');
  scrollTopBtn.onclick = () => {
    appRoot.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // LocalStorage Background Load
  const appRoot = document.getElementById('appRoot');
  const savedBg = localStorage.getItem('eagle_bg');
  if (savedBg) {
    appRoot.style.background = savedBg;
  }

  window.setBgColor = function(color, textColor) {
    appRoot.style.background = color;
    localStorage.setItem('eagle_bg', color);
  };

  const customColorPicker = document.getElementById('customColorPicker');
  const customHexInput = document.getElementById('customHexInput');
  customColorPicker.oninput = (e) => {
    appRoot.style.background = e.target.value;
    customHexInput.value = e.target.value;
    localStorage.setItem('eagle_bg', e.target.value);
  };
  customHexInput.onchange = (e) => {
    appRoot.style.background = e.target.value;
    localStorage.setItem('eagle_bg', e.target.value);
  };

  // Escape Key Setup & Toggle
  const escToggle = document.getElementById('escToggle');
  const savedEsc = localStorage.getItem('eagle_esc');
  if (savedEsc !== null) {
    escToggle.checked = (savedEsc === 'true');
  }
  escToggle.onchange = () => {
    localStorage.setItem('eagle_esc', escToggle.checked);
  };

  window.addEventListener('keydown', (e) => {
    if (e.key === "'" && escToggle.checked) {
      window.location.href = "https://www.google.com";
    }
  });

  // Favorites System
  let favorites = JSON.parse(localStorage.getItem('eagle_favorites') || '[]');

  function updateFavUI() {
    document.querySelectorAll('.game-card').forEach(card => {
      const id = card.getAttribute('data-id');
      const star = card.querySelector('.fav-star');
      if (favorites.includes(id)) {
        star.classList.add('active');
        star.textContent = '★';
      } else {
        star.classList.remove('active');
        star.textContent = '☆';
      }
    });
    filterGames();
  }

  window.toggleFavorite = function(id) {
    if (favorites.includes(id)) {
      favorites = favorites.filter(fav => fav !== id);
    } else {
      favorites.push(id);
    }
    localStorage.setItem('eagle_favorites', JSON.stringify(favorites));
    updateFavUI();
  };

  const gameFilter = document.getElementById('gameFilter');
  gameFilter.onchange = filterGames;

  function filterGames() {
    const filterVal = gameFilter.value;
    document.querySelectorAll('.game-card').forEach(card => {
      const id = card.getAttribute('data-id');
      if (filterVal === 'favorites' && !favorites.includes(id)) {
        card.style.display = 'none';
      } else {
        card.style.display = 'flex';
      }
    });
  }

  updateFavUI();

  // JSONBin Live Sync setup
  const BIN_URL = "https://api.jsonbin.io/v3/b/6adafef5ac6210605a4b0a6d";
  const MASTER_KEY = "YOUR_MASTER_KEY_HERE";

  async function syncAnnouncement() {
    try {
      const res = await fetch(BIN_URL, { headers: { 'X-Master-Key': MASTER_KEY } });
      const data = await res.json();
      if (data && data.record && data.record.message) {
        document.getElementById('globalBanner').textContent = `📢 ${data.record.message}`;
      }
    } catch (err) {
      console.log('JSONBin sync offline or key unconfigured');
    }
  }
  syncAnnouncement();

  // Drawer Controls
  const menuBtn = document.getElementById('menuBtn');
  const drawer = document.getElementById('drawer');
  const drawerOverlay = document.getElementById('drawerOverlay');
  const closeDrawer = document.getElementById('closeDrawer');

  function toggleDrawer(open) {
    drawer.classList.toggle('open', open);
    drawerOverlay.classList.toggle('open', open);
  }

  menuBtn.onclick = () => toggleDrawer(true);
  closeDrawer.onclick = () => toggleDrawer(false);
  drawerOverlay.onclick = () => toggleDrawer(false);

  // Owner Keypad
  const ownerMenuBtn = document.getElementById('ownerMenuBtn');
  const ownerModal = document.getElementById('ownerModal');
  const cancelOwner = document.getElementById('cancelOwner');
  const codeDisplay = document.getElementById('codeDisplay');
  const ownerBroadcastPanel = document.getElementById('ownerBroadcastPanel');
  const sendBroadcastBtn = document.getElementById('sendBroadcastBtn');
  const broadcastInput = document.getElementById('broadcastInput');

  let enteredCode = '';

  ownerMenuBtn.onclick = () => {
    toggleDrawer(false);
    enteredCode = '';
    codeDisplay.textContent = '____';
    ownerBroadcastPanel.style.display = 'none';
    ownerModal.classList.add('open');
  };
  cancelOwner.onclick = () => ownerModal.classList.remove('open');

  window.pressKey = function(num) {
    if (enteredCode.length < 4) {
      enteredCode += num;
      codeDisplay.textContent = enteredCode.padEnd(4, '_');
      if (enteredCode.length === 4) {
        if (enteredCode === '3166') {
          ownerBroadcastPanel.style.display = 'flex';
        } else {
          alert('Incorrect Code!');
          enteredCode = '';
          codeDisplay.textContent = '____';
        }
      }
    }
  };

  sendBroadcastBtn.onclick = async () => {
    const msg = broadcastInput.value.trim();
    if (msg) {
      try {
        sendBroadcastBtn.textContent = 'Publishing...';
        await fetch(BIN_URL, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json', 'X-Master-Key': MASTER_KEY },
          body: JSON.stringify({ message: msg })
        });
        alert('Broadcast live!');
        ownerModal.classList.remove('open');
        syncAnnouncement();
      } catch (e) {
        alert('Broadcast failed.');
      } finally {
        sendBroadcastBtn.textContent = 'Broadcast Live';
      }
    }
  };

  // Bug Report
  const reportBtn = document.getElementById('reportBtn');
  const bugModal = document.getElementById('bugModal');
  const cancelBug = document.getElementById('cancelBug');
  const submitBug = document.getElementById('submitBug');

  reportBtn.onclick = () => { toggleDrawer(false); bugModal.classList.add('open'); };
  cancelBug.onclick = () => bugModal.classList.remove('open');
  submitBug.onclick = () => {
    alert('Bug report submitted!');
    bugModal.classList.remove('open');
  };
});
